from html.parser import HTMLParser
import sys

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tags = []
    def handle_starttag(self, tag, attrs):
        if tag not in ['br', 'hr', 'img', 'input', 'meta', 'link', 'area', 'base', 'col', 'embed', 'param', 'source', 'track', 'wbr']:
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if self.tags and self.tags[-1] == tag:
            self.tags.pop()
    def handle_data(self, data):
        pass

with open('/app/output/final_report.html', 'r') as f:
    content = f.read()
print(f'File size: {len(content):,} bytes')
v = Validator()
try:
    v.feed(content)
    print('HTML parsing: OK')
    print(f'Unclosed tags (sample): {v.tags[:5] if v.tags else \"None\"}')
except Exception as e:
    print(f'HTML error: {e}')

# Check key sections exist
checks = ['Executive Summary', 'Price Trend', 'Volatility', 'Volume', 'Annual', 'Key Takeaways', 
          'img src=\"data:image/png;base64', 'KPI', 'chart']
for c in checks:
    found = c in content
    print(f'  [{\"✓\" if found else \"✗\"}] {c}')
